    constructor(C _c) { c = _c; }

    // single entrypoint performing the property test
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // initial observed balance for this contract and for c
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        uint beforeCallerBal = c.balances(address(this));

        // Deposit into c from this contract
        c.Deposit{value: depositAmount}();

        // read balances after deposit
        uint afterCallerBal_afterDeposit = c.balances(address(this));
        uint afterC_afterDeposit = address(c).balance;

        // Ensure deposit had the expected observable effect (non-decreasing of caller balance)
        // This is not the final assert; it helps establish meaningful state before Collect.
        // Note: avoid using require that depends on c's internals beyond its public getters.
        assert(afterCallerBal_afterDeposit >= beforeCallerBal);
        assert(afterC_afterDeposit >= beforeC);

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-state
        uint afterCallerBal = c.balances(address(this));
        uint afterC = address(c).balance;

        // If Collect succeeded then caller's recorded balance must have decreased by exactly collectAmount
        // and the contract's Ether balance must have decreased by at least collectAmount (transfer could fail earlier but Collect reverts on failed send,
        // so when not reverted Ether leaves c). If reverted is true, no strong relation required.
        assert(reverted || (afterCallerBal + collectAmount == afterCallerBal_afterDeposit && afterC + collectAmount <= afterC_afterDeposit));
    }

    receive() external payable { }
}

