contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take params: minSum to set, deposit amount, and collect amount to attempt.
    // This function will: set MinSum, deposit funds, then attempt Collect(_am).
    function run(uint _minSum, uint _deposit, uint _am) public payable {
        // ensure this contract has enough ETH to forward the deposit
        if (_deposit > 0) require(address(this).balance >= _deposit);

        // Before any actions, read observable state
        uint beforeContractBalance = address(this).balance;
        uint beforeCBalanceRecord = c.balances(address(this));

        // Configure c: set MinSum and initialize Log pointer if needed (Log address not known; skip)
        // Both SetMinSum and SetLogFile require !intitalized; we only call SetMinSum which is allowed once.
        c.SetMinSum(_minSum);

        // Deposit into c (via Deposit payable). Must be top-level statement.
        if (_deposit > 0) {
            c.Deposit{value: _deposit}();
        } else {
            // allow calling Deposit with zero value as well
            c.Deposit{value: 0}();
        }

        // Record values after deposit, before Collect
        uint afterDepositRecorded = c.balances(address(this));
        uint afterDepositContractBalance = address(c).balance;
        uint ourBalanceAfterDeposit = address(this).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCollectRecorded = c.balances(address(this));
        uint afterCollectContractBalance = address(c).balance;
        uint ourBalanceAfterCollect = address(this).balance;

        // General property: If Collect succeeded (not reverted) then the recorded balance decreased by exactly _am,
        // the contract's Ether balance decreased by exactly _am, and our balance increased by exactly _am.
        // Also Collect can only succeed when pre-Collect recorded balance >= MinSum and >= _am.
        uint preCollectRecorded = afterDepositRecorded;
        uint minSum = c.MinSum();

        assert(
            reverted
            ? (
                // If it reverted, then either preCollectRecorded < minSum or preCollectRecorded < _am
                (preCollectRecorded < minSum) || (preCollectRecorded < _am) || (afterCollectRecorded == preCollectRecorded)
              )
            : (
                // If not reverted: recorded decreased by _am and balances moved accordingly and preconditions held
                (preCollectRecorded >= minSum)
                && (preCollectRecorded >= _am)
                && (afterCollectRecorded + _am == preCollectRecorded)
                && (afterCollectContractBalance + _am == afterDepositContractBalance)
                && (ourBalanceAfterCollect == ourBalanceAfterDeposit + _am)
              )
        );
    }

    // Allow this contract to receive refunds when c sends Ether
    receive() external payable {}
}

contract InvMutTest {
