    // params: _minSum to set, _deposit to send into c, _am to attempt to Collect
    function run(uint _minSum, uint _deposit, uint _am) public payable {
        // ensure this test contract has enough ETH to forward the deposit
        if (_deposit > 0) require(address(this).balance >= _deposit);

        // Set MinSum once (allowed because c is fresh)
        c.SetMinSum(_minSum);

        // Perform Deposit (top-level state-changing call)
        c.Deposit{value: _deposit}();

        // Read observable state before attempting Collect
        uint preCollectRecorded = c.balances(address(this));
        uint minSum = c.MinSum();
        uint contractBalanceBeforeCollect = address(c).balance;
        uint ourBalanceBeforeCollect = address(this).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after Collect attempt
        uint postCollectRecorded = c.balances(address(this));
        uint contractBalanceAfterCollect = address(c).balance;
        uint ourBalanceAfterCollect = address(this).balance;

        // General invariant:
        // If Collect succeeded then:
        //  - preCollectRecorded >= minSum && preCollectRecorded >= _am
        //  - recorded balance decreased by exactly _am
        //  - c's Ether balance decreased by exactly _am
        //  - this contract's Ether balance increased by exactly _am
        // If Collect reverted then at least one of the preconditions was false or nothing changed.
        assert(
            reverted
            ? (
                // If reverted, either preconditions false or balances unchanged
                (preCollectRecorded < minSum) || (preCollectRecorded < _am) || (
                    postCollectRecorded == preCollectRecorded &&
                    contractBalanceAfterCollect == contractBalanceBeforeCollect &&
                    ourBalanceAfterCollect == ourBalanceBeforeCollect
                )
              )
            : (
                // If not reverted, then exactly the expected transfers and checks occurred
                (preCollectRecorded >= minSum) &&
                (preCollectRecorded >= _am) &&
                (postCollectRecorded + _am == preCollectRecorded) &&
                (contractBalanceAfterCollect + _am == contractBalanceBeforeCollect) &&
                (ourBalanceAfterCollect == ourBalanceBeforeCollect + _am)
              )
        );
    }

    // Allow receiving Ether when c sends funds back
    receive() external payable {}
}

