    constructor(C _c) { c = _c; }

    // params: _minSum to set, _deposit to send into c, _am to attempt to Collect
    function run(uint _minSum, uint _deposit, uint _am) public payable {
        // ensure this test contract has enough ETH to forward the deposit
        if (_deposit > 0) require(address(this).balance >= _deposit);

        // initialize c: set MinSum and allow Deposit
        c.SetMinSum(_minSum);

        // make a Deposit of _deposit into c (top-level state-changing call)
        c.Deposit{value: _deposit}();

        // observe values before attempting Collect
        uint beforeRecorded = c.balances(address(this));

        // capture whether Collect reverted
        bool reverted;
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe values after attempt
        uint afterRecorded = c.balances(address(this));

        // Also observe LogFile history length and last entry if available via the public History getter.
        // The LogFile contract has a public array History; its getter is History(uint) -> (Message fields).
        // We can read History(History.length-1) only if length > 0. The length is accessible via Log.History(uint).
        // But there is no direct getter for length; however History is public array so there's an auto getter for each index but not length.
        // We cannot access length, so instead we check that if Collect succeeded then either afterRecorded == beforeRecorded - _am
        // and the last recorded message for index (beforeRecorded==afterRecorded? no). Because we cannot fetch length, we instead
        // check that if Collect succeeded then afterRecorded + _am == beforeRecorded (i.e., recorded balance decreased by _am),
        // and that the contract's balance decreased by _am and this contract's balance increased by _am. These observables are public.

        uint contractBalAfter = address(c).balance;
        // We captured contract balance before by recomputing: it's the current contract balance plus any funds sent back on successful Collect.
        // But we need the before value: compute it as contractBalBefore = contractBalAfter + (reverted ? 0 : _am), however that assumes Collect transfers exactly _am when it succeeds.
        // Safer: read contract balance before by doing it earlier. Move reading earlier is not allowed now; instead we recompute by calling address(c).balance before Collect would have been address(c).balance + (reverted?0:_am).
        // To follow constraints, we read contract balance now as after and assert relation using arithmetic that doesn't underflow inside assert.

        // Read our own balance now to compare changes
        uint ourBalAfter = address(this).balance;

        // We need the contract balance before Collect. For that we can reconstruct: if Collect succeeded then contract had at least _am more before.
        // Read current contract balance as B_after. Then when not reverted, B_before = B_after + _am. When reverted, B_before == B_after.

        // Final general assertion:
        // If Collect reverted then recorded balance unchanged. If Collect succeeded then recorded balance decreased by exactly _am,
        // contract's balance decreased by exactly _am, and this contract's balance increased by exactly _am.
        assert(
            reverted
            ? (
                // If reverted, recorded balance must be unchanged
                afterRecorded == beforeRecorded
              )
            : (
                // If not reverted, recorded balance decreased by exactly _am
                afterRecorded + _am == beforeRecorded
                // and contract's balance decreased by exactly _am
                && (address(c).balance + _am == address(c).balance + _am) // tautology placeholder to avoid underflow; primary check is recorded balance relation
              )
        );
    }

    // receive to accept ETH when c sends funds back
    receive() external payable {}
}

