    C c;
    constructor(C _c) { c = _c; }

    // params: _minSum to set, _deposit to send into c
    function run(uint _minSum, uint _deposit) public payable {
        // ensure this test contract has enough ETH to forward the deposit
        if (_deposit > 0) require(address(this).balance >= _deposit);

        // initialize c so Deposit is allowed
        c.SetMinSum(_minSum);

        // read recorded balance before Deposit
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Deposit of _deposit into c (top-level state-changing call)
        c.Deposit{value: _deposit}();

        // read after-values
        uint afterRecorded = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // General rule (one assert): a Deposit call by this contract never decreases its recorded balance
        // and the contract's on-chain balance increased by at least the sent amount.
        // (We use >= to allow for edge cases where logs or reverts could alter behavior; but recorded balance must not decrease.)
        assert(afterRecorded >= beforeRecorded && afterContractBal >= beforeContractBal + _deposit);
