        c.SetMinSum(initMin);
        c.SetLogFile(address(this));
        c.Initialized();

        // deposit dep into contract c (this increases c.balances(this) and address(c).balance)
        c.Deposit{value: dep}();

        // record before-values
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

