            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterRecorded = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect returned (did not revert) then it must have sent exactly 'want' (subject to availability):
        // - recorded balance decreased by exactly min(want, beforeRecorded) but Collect only proceeds when beforeRecorded>=initMin and beforeRecorded>=want,
        //   therefore when not reverted we expect beforeRecorded >= initMin && beforeRecorded >= want, and afterRecorded == beforeRecorded - want
        // - contract balance decreased by exactly want as well.
        // If Collect reverted then nothing changed: recorded and contract balances equal prior values.
        assert(
            reverted
            ? (afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
            : (
                // when not reverted, the before conditions must have held
                beforeRecorded >= initMin && beforeRecorded >= want
                && afterRecorded + want == beforeRecorded
                && afterContractBal + want == beforeContractBal
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    //   initMin: value to set as MinSum
    //   dep: amount to deposit so this contract has a balance in c
    //   want: amount to attempt to collect
    function run(uint initMin, uint dep, uint want) public payable {
        // ensure we have funds to deposit
        require(address(this).balance >= dep);

        // configure and finalize initialization
        c.SetMinSum(initMin);
        c.SetLogFile(address(this));
        c.Initialized();

        // deposit 'dep' into c so the caller recorded balance increases
        c.Deposit{value: dep}();

        // read before-values
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(want) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterRecorded = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // If not reverted: recorded balance strictly decreases and contract balance strictly decreases,
        // and the decreases are equal (both decreased by the transferred amount > 0).
        // If reverted: both recorded and contract balances unchanged.
        assert(
            reverted
            ? (afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
            : (
                // when successful, both balances must have decreased
                afterRecorded < beforeRecorded
                && afterContractBal < beforeContractBal
                // and the magnitudes of decrease must be equal
                && (beforeRecorded - afterRecorded) == (beforeContractBal - afterContractBal)
            )
        );
    }

